import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Glassmorphism customization utilities
 * Allows users to customize color, transparency, blur, and outline for glass effects
 */

export interface GlassCustomization {
  /**
   * Background color for the glass effect (e.g., "oklch(100% 0 0 / 0.1)")
   * Default: uses CSS variable --glass-bg
   */
  color?: string;

  /**
   * Transparency/opacity for the background (0-1)
   * If provided, will override the alpha channel in color
   */
  transparency?: number;

  /**
   * Overall glass solidity (0–1). 0 = the variant's natural sheer glass (default), 1 = fully solid. Sets the
   * `--glass-opacity` floor the glass utilities read — keeps the tint / gradient / blur, just makes the
   * surface less see-through. (Unlike `transparency`, which replaces the whole background with flat white.)
   */
  opacity?: number;

  /**
   * Blur amount in pixels
   * Default: uses CSS variable --blur (20px)
   */
  blur?: number | string;

  /**
   * Border/outline color (e.g., "oklch(100% 0 0 / 0.25)")
   * Default: uses CSS variable --glass-border
   */
  outline?: string;

  /**
   * Border/outline width in pixels
   * Default: 1px
   */
  outlineWidth?: number | string;

  /**
   * Shadow for the glass effect
   * Default: uses CSS variable --glass-shadow
   */
  shadow?: string;

  /**
   * Inner glow color and intensity (e.g., "oklch(100% 0 0 / 0.2)")
   * Creates an inset shadow for a glowing effect inside the element
   */
  innerGlow?: string;

  /**
   * Inner glow blur/spread radius in pixels
   * Default: 20px
   */
  innerGlowBlur?: number | string;
}

/**
 * Set or replace the alpha channel on any CSS color string.
 * Handles oklch(), hex, and rgb/rgba formats — always outputs oklch.
 */
function setAlpha(color: string, alpha: number): string {
  // oklch(...) — replace or append alpha
  const oklchMatch = color.match(/^oklch\(([^/)]+?)(?:\s*\/\s*[\d.]+)?\)$/);
  if (oklchMatch) {
    return `oklch(${oklchMatch[1].trim()} / ${alpha})`;
  }

  // hex — convert to oklch with alpha
  if (color.startsWith("#")) {
    const hex = color.replace("#", "");
    const r = parseInt(hex.substring(0, 2), 16) / 255;
    const g = parseInt(hex.substring(2, 4), 16) / 255;
    const b = parseInt(hex.substring(4, 6), 16) / 255;
    // Approximate lightness for simple hex fallback
    const l = 0.2126 * r + 0.7152 * g + 0.0722 * b;
    return `oklch(${(l * 100).toFixed(1)}% 0 0 / ${alpha})`;
  }

  // rgb/rgba — convert to oklch with alpha
  const rgbaMatch = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
  if (rgbaMatch) {
    const l = (0.2126 * +rgbaMatch[1] + 0.7152 * +rgbaMatch[2] + 0.0722 * +rgbaMatch[3]) / 255;
    return `oklch(${(l * 100).toFixed(1)}% 0 0 / ${alpha})`;
  }

  // Unknown format — wrap with color-mix as fallback
  return `color-mix(in oklch, ${color} ${Math.round(alpha * 100)}%, transparent)`;
}

/**
 * Converts glass customization props to CSS style object
 */
export function getGlassStyles(customization?: GlassCustomization): React.CSSProperties {
  if (!customization) return {};

  const styles = {} as React.CSSProperties & Record<`--${string}`, string | number>;

  // Handle background color and transparency
  if (customization.color || customization.transparency !== undefined) {
    let bgColor = customization.color || "oklch(100% 0 0 / 0.1)";

    if (customization.transparency !== undefined) {
      bgColor = setAlpha(bgColor, customization.transparency);
    }

    styles.backgroundColor = bgColor;
  }

  // Overall solidity — sets the --glass-opacity floor the glass utilities lay behind the surface (0 = the
  // variant's natural sheer glass, 1 = fully solid). Keeps the tint / gradient / blur intact.
  if (customization.opacity !== undefined) {
    styles["--glass-opacity"] = customization.opacity;
  }

  // Handle blur
  if (customization.blur !== undefined) {
    const blurValue = typeof customization.blur === "number" ? `${customization.blur}px` : customization.blur;
    styles.backdropFilter = `blur(${blurValue})`;
    styles.WebkitBackdropFilter = `blur(${blurValue})`; // Safari support
  }

  // Handle outline/border - always apply border for glassmorphism effect
  if (customization.outline !== undefined) {
    const width = customization.outlineWidth || "1px";
    styles.borderColor = customization.outline;
    styles.borderWidth = typeof width === "number" ? `${width}px` : width;
    styles.borderStyle = "solid";
  } else if (!customization.outline && (customization.color || customization.transparency !== undefined || customization.blur !== undefined)) {
    // Apply default border if glass customization is provided but outline is not
    styles.borderColor = "oklch(100% 0 0 / 0.3)";
    styles.borderWidth = "1px";
    styles.borderStyle = "solid";
  }

  // Handle shadow and inner glow - combine both if provided
  const shadows: string[] = [];

  // Add outer shadow
  if (customization.shadow !== undefined) {
    shadows.push(customization.shadow);
  } else if (customization.color || customization.transparency !== undefined || customization.blur !== undefined) {
    // Apply default glass shadow for depth
    shadows.push("0 8px 32px oklch(0% 0 0 / 0.1), 0 2px 8px oklch(0% 0 0 / 0.05)");
  }

  // Add inner glow as inset shadow
  if (customization.innerGlow !== undefined) {
    const glowBlur =
      customization.innerGlowBlur !== undefined
        ? typeof customization.innerGlowBlur === "number"
          ? `${customization.innerGlowBlur}px`
          : customization.innerGlowBlur
        : "20px";
    shadows.push(`inset 0 0 ${glowBlur} ${customization.innerGlow}`);
  }

  if (shadows.length > 0) {
    styles.boxShadow = shadows.join(", ");
  }

  return styles;
}

/**
 * Generates CSS custom properties for glass customization
 * Useful for components that need to pass styles to child elements
 */
export function getGlassCSSVars(customization?: GlassCustomization): Record<string, string> {
  if (!customization) return {};

  const vars: Record<string, string> = {};

  if (customization.color || customization.transparency !== undefined) {
    let bgColor = customization.color || "oklch(100% 0 0 / 0.1)";

    if (customization.transparency !== undefined) {
      bgColor = setAlpha(bgColor, customization.transparency);
    }

    vars["--glass-bg-custom"] = bgColor;
  }

  if (customization.opacity !== undefined) {
    vars["--glass-opacity"] = String(customization.opacity);
  }

  if (customization.blur !== undefined) {
    const blurValue = typeof customization.blur === "number" ? `${customization.blur}px` : customization.blur;
    vars["--blur-custom"] = blurValue;
  }

  if (customization.outline !== undefined) {
    vars["--glass-border-custom"] = customization.outline;
  }

  if (customization.outlineWidth !== undefined) {
    const width = typeof customization.outlineWidth === "number" ? `${customization.outlineWidth}px` : customization.outlineWidth;
    vars["--glass-border-width-custom"] = width;
  }

  if (customization.shadow !== undefined) {
    vars["--glass-shadow-custom"] = customization.shadow;
  }

  if (customization.innerGlow !== undefined) {
    vars["--glass-inner-glow-custom"] = customization.innerGlow;
  }

  if (customization.innerGlowBlur !== undefined) {
    const blurValue = typeof customization.innerGlowBlur === "number" ? `${customization.innerGlowBlur}px` : customization.innerGlowBlur;
    vars["--glass-inner-glow-blur-custom"] = blurValue;
  }

  return vars;
}

import { cva } from "class-variance-authority";

/**
 * Shared hover effect variants for all Sistine components
 *
 * Effects:
 * - none: No hover effect
 * - glow: Themed glow shadow (--glass-glow, follows the tint hue) that intensifies on hover
 * - shimmer: Moving shimmer effect across the component
 * - ripple: Ripple effect that scales outward on hover
 * - lift: Subtle lift effect with shadow increase
 * - scale: Scale up slightly on hover
 */
export const hoverEffects = cva("transition duration-300", {
  variants: {
    hover: {
      none: "",
      glow: "glass-glow hover:glass-glow-lg",
      shimmer:
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-white/20 before:to-transparent hover:before:translate-x-full before:transition-transform before:duration-1000",
      ripple:
        "relative overflow-hidden after:absolute after:inset-0 after:scale-0 after:rounded-full after:bg-white/30 after:transition-transform after:duration-500 hover:after:scale-150",
      lift: "hover:-translate-y-1 hover:shadow-lg",
      scale: "hover:scale-105",
    },
  },
  defaultVariants: {
    hover: "none",
  },
});

export type HoverEffect = "none" | "glow" | "shimmer" | "ripple" | "lift" | "scale";

"use client";

import { CaretRightIcon, Check, Circle } from "@phosphor-icons/react";
import { cva, type VariantProps } from "class-variance-authority";
import { DropdownMenu as DropdownMenuPrimitive } from "radix-ui";
import * as React from "react";

import { type Material, resolveMaterial } from "@/lib/material";
import { cn } from "@/lib/utils";

/* Variant classes carry BEHAVIOR only; the surface comes from resolveMaterial. */
const dropdownMenuSubContentVariants = cva(
  "z-50 min-w-[8rem] origin-(--radix-dropdown-menu-content-transform-origin) overflow-hidden rounded-xl p-1 shadow-lg data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
  {
    variants: {
      variant: {
        default: "bg-popover text-popover-foreground border",
        glass: "text-foreground",
        frosted: "text-foreground",
        crystal: "text-foreground",
        opaque: "text-foreground",
        surface: "text-foreground",
        solid: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "glass",
    },
  },
);

const dropdownMenuContentVariants = cva(
  "z-50 max-h-(--radix-dropdown-menu-content-available-height) min-w-[8rem] origin-(--radix-dropdown-menu-content-transform-origin) overflow-x-hidden overflow-y-auto rounded-xl p-1 shadow-md data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
  {
    variants: {
      variant: {
        default: "bg-popover text-popover-foreground border",
        glass: "text-foreground",
        frosted: "text-foreground",
        crystal: "text-foreground",
        opaque: "text-foreground",
        surface: "text-foreground",
        solid: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "glass",
    },
  },
);

/* Role: bordered + veiled adaptive glass (the old glass-solid look). */
const ROLE = {
  border: true,
  veil: true,
};

const DropdownMenu = ({ ...props }: React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Root>) => (
  <DropdownMenuPrimitive.Root data-slot="dropdown-menu" {...props} />
);
DropdownMenu.displayName = DropdownMenuPrimitive.Root.displayName;

const DropdownMenuTrigger = ({ ...props }: React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Trigger>) => (
  <DropdownMenuPrimitive.Trigger data-slot="dropdown-menu-trigger" {...props} />
);
DropdownMenuTrigger.displayName = DropdownMenuPrimitive.Trigger.displayName;

const DropdownMenuGroup = ({ ...props }: React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Group>) => (
  <DropdownMenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />
);
DropdownMenuGroup.displayName = DropdownMenuPrimitive.Group.displayName;

const DropdownMenuPortal = ({ ...props }: React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Portal>) => (
  <DropdownMenuPrimitive.Portal data-slot="dropdown-menu-portal" {...props} />
);
DropdownMenuPortal.displayName = DropdownMenuPrimitive.Portal.displayName;

const DropdownMenuSub = ({ ...props }: React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Sub>) => (
  <DropdownMenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />
);
DropdownMenuSub.displayName = DropdownMenuPrimitive.Sub.displayName;

const DropdownMenuRadioGroup = ({ ...props }: React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioGroup>) => (
  <DropdownMenuPrimitive.RadioGroup data-slot="dropdown-menu-radio-group" {...props} />
);
DropdownMenuRadioGroup.displayName = DropdownMenuPrimitive.RadioGroup.displayName;

const DropdownMenuSubTrigger = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.SubTrigger>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubTrigger> & {
    inset?: boolean;
  }
>(({ className, inset, children, ...props }, ref) => (
  <DropdownMenuPrimitive.SubTrigger
    ref={ref}
    data-slot="dropdown-menu-sub-trigger"
    data-inset={inset}
    className={cn(
      "flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none focus:bg-foreground/10 focus:text-accent-foreground data-[inset]:pl-8 data-[state=open]:bg-foreground/10 data-[state=open]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
      inset && "pl-8",
      className,
    )}
    {...props}
  >
    {children}
    <CaretRightIcon className="ml-auto h-4 w-4" />
  </DropdownMenuPrimitive.SubTrigger>
));
DropdownMenuSubTrigger.displayName = DropdownMenuPrimitive.SubTrigger.displayName;

const DropdownMenuSubContent = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.SubContent>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubContent> &
    VariantProps<typeof dropdownMenuSubContentVariants> & {
      material?: Material;
      border?: boolean;
      veil?: boolean;
      glow?: boolean | "lg";
    }
>(({ className, variant = "glass", material, border, veil, glow, ...props }, ref) => {
  const m = resolveMaterial(ROLE, variant === "default" ? null : variant, {
    material,
    border,
    veil,
    glow,
  });

  return (
    <DropdownMenuPrimitive.SubContent
      ref={ref}
      data-slot="dropdown-menu-sub-content"
      data-material={m?.["data-material"]}
      className={cn(
        m?.className,
        dropdownMenuSubContentVariants({
          variant,
        }),
        className,
      )}
      {...props}
    />
  );
});
DropdownMenuSubContent.displayName = DropdownMenuPrimitive.SubContent.displayName;

const DropdownMenuContent = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Content> &
    VariantProps<typeof dropdownMenuContentVariants> & {
      material?: Material;
      border?: boolean;
      veil?: boolean;
      glow?: boolean | "lg";
    }
>(({ className, sideOffset = 4, variant = "glass", material, border, veil, glow, ...props }, ref) => {
  const m = resolveMaterial(ROLE, variant === "default" ? null : variant, {
    material,
    border,
    veil,
    glow,
  });

  return (
    <DropdownMenuPrimitive.Portal>
      <DropdownMenuPrimitive.Content
        ref={ref}
        data-slot="dropdown-menu-content"
        data-material={m?.["data-material"]}
        sideOffset={sideOffset}
        className={cn(
          m?.className,
          dropdownMenuContentVariants({
            variant,
          }),
          className,
        )}
        {...props}
      />
    </DropdownMenuPrimitive.Portal>
  );
});
DropdownMenuContent.displayName = DropdownMenuPrimitive.Content.displayName;

const DropdownMenuItem = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Item> & {
    inset?: boolean;
    variant?: "default" | "destructive";
  }
>(({ className, inset, variant = "default", ...props }, ref) => (
  <DropdownMenuPrimitive.Item
    ref={ref}
    data-slot="dropdown-menu-item"
    data-inset={inset}
    data-variant={variant}
    className={cn(
      "relative flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none transition-colors focus:bg-foreground/10 focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 data-[inset]:pl-8 data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive dark:data-[variant=destructive]:focus:bg-destructive/20 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground data-[variant=destructive]:*:[svg]:text-destructive!",
      inset && "pl-8",
      className,
    )}
    {...props}
  />
));
DropdownMenuItem.displayName = DropdownMenuPrimitive.Item.displayName;

const DropdownMenuCheckboxItem = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.CheckboxItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.CheckboxItem>
>(({ className, children, checked, ...props }, ref) => (
  <DropdownMenuPrimitive.CheckboxItem
    ref={ref}
    data-slot="dropdown-menu-checkbox-item"
    className={cn(
      "relative flex cursor-default select-none items-center gap-2 rounded-sm py-1.5 pl-8 pr-2 text-sm outline-none transition-colors focus:bg-foreground/10 focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
      className,
    )}
    checked={checked}
    {...props}
  >
    <span className="pointer-events-none absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
      <DropdownMenuPrimitive.ItemIndicator>
        <Check className="h-4 w-4" />
      </DropdownMenuPrimitive.ItemIndicator>
    </span>
    {children}
  </DropdownMenuPrimitive.CheckboxItem>
));
DropdownMenuCheckboxItem.displayName = DropdownMenuPrimitive.CheckboxItem.displayName;

const DropdownMenuRadioItem = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.RadioItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioItem>
>(({ className, children, ...props }, ref) => (
  <DropdownMenuPrimitive.RadioItem
    ref={ref}
    data-slot="dropdown-menu-radio-item"
    className={cn(
      "relative flex cursor-default select-none items-center gap-2 rounded-sm py-1.5 pl-8 pr-2 text-sm outline-none transition-colors focus:bg-foreground/10 focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
      className,
    )}
    {...props}
  >
    <span className="pointer-events-none absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
      <DropdownMenuPrimitive.ItemIndicator>
        <Circle className="h-2 w-2 fill-current" />
      </DropdownMenuPrimitive.ItemIndicator>
    </span>
    {children}
  </DropdownMenuPrimitive.RadioItem>
));
DropdownMenuRadioItem.displayName = DropdownMenuPrimitive.RadioItem.displayName;

const DropdownMenuLabel = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Label> & {
    inset?: boolean;
  }
>(({ className, inset, ...props }, ref) => (
  <DropdownMenuPrimitive.Label
    ref={ref}
    data-slot="dropdown-menu-label"
    data-inset={inset}
    className={cn("px-2 py-1.5 text-sm font-semibold data-[inset]:pl-8", inset && "pl-8", className)}
    {...props}
  />
));
DropdownMenuLabel.displayName = DropdownMenuPrimitive.Label.displayName;

const DropdownMenuSeparator = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <DropdownMenuPrimitive.Separator ref={ref} data-slot="dropdown-menu-separator" className={cn("-mx-1 my-1 h-px bg-muted", className)} {...props} />
));
DropdownMenuSeparator.displayName = DropdownMenuPrimitive.Separator.displayName;

const DropdownMenuShortcut = ({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) => {
  return <span data-slot="dropdown-menu-shortcut" className={cn("ml-auto text-xs tracking-widest opacity-60", className)} {...props} />;
};
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

export {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPortal,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
};

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  DropdownMenu as BaseDropdownMenu,
  DropdownMenuContent as BaseDropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "../dropdown-menu";

export interface DropdownMenuContentProps extends React.ComponentProps<typeof BaseDropdownMenuContent> {
  glow?: boolean;
}

/**
 * Sistine Dropdown Menu - Enhanced dropdown menu with glassy effects
 */
export const DropdownMenuContent = React.forwardRef<React.ElementRef<typeof BaseDropdownMenuContent>, DropdownMenuContentProps>(
  ({ className, variant = "glass", glow = false, ...props }, ref) => {
    return <BaseDropdownMenuContent ref={ref} variant={variant} className={cn(glow && "glass-glow", className)} {...props} />;
  },
);
DropdownMenuContent.displayName = "DropdownMenuContent";

export { BaseDropdownMenu as DropdownMenu, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger };
